:\"zu\",\"enabled\":false,\"url_path\":\"/zu/\"}],\"breadcrumb\":[{\"url_path\":\"/en/library/\",\"title\":\"Library\"},{\"url_path\":\"/en/library/bg/\",\"title\":\"Bhagavad-gītā As It Is\"},{\"url_path\":\"/en/library/bg/4/\",\"title\":\"Chapter Four: Transcendental Knowledge\"}],\"url_path\":\"/en/library/bg/4/29/\",\"bb\":1300,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/4/28/\",\"title\":\"TEXT 28\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/4/30/\",\"title\":\"TEXT 30\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":1466,\"bb\":568067,\"url_path\":\"/en/library/bg/4/29/devanagari/\",\"body_final\":\"अपाने जुह्वति प्राणं प्राणेऽपानं तथापरे ।
प्राणापानगती रुद्ध्वा प्राणायामपरायणाः ।
अपरे नियताहाराः प्राणान्प्राणेषु जुह्वति ॥ २९ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":1467,\"bb\":1301,\"url_path\":\"/en/library/bg/4/29/b1301/\",\"body_value\":\"apāne juhvati prāṇaṁ
prāṇe ’pānaṁ tathāpare
prāṇāpāna-gatī ruddhvā
prāṇāyāma-parāyaṇāḥ
apare niyatāhārāḥ
prāṇān prāṇeṣu juhvati\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":1468,\"bb\":1302,\"url_path\":\"/en/library/bg/4/29/b1302/\",\"shadow_value\":\"apāne – in the air which acts downward; juhvati – offer; prāṇam – the air which acts outward; prāṇe – in the air going outward; apānam – the air going downward; tathā – as also; apare – others; prāṇa – of the air going outward; apāna – and the air going downward; gatī – the movement; ruddhvā – checking; prāṇa-āyāma – trance induced by stopping all breathing; parāyaṇāḥ – so inclined; apare – others; niyata – having controlled; āhārāḥ – eating; prāṇān – the outgoing air; prāṇeṣu – in the outgoing air; juhvati – sacrifice.\",\"word_for_word_value\":[{\"word\":\"apāne\",\"translation\":\"in the air which acts downward\"},{\"word\":\"juhvati\",\"translation\":\"offer\"},{\"word\":\"prāṇam\",\"translation\":\"the air which acts outward\"},{\"word\":\"prāṇe\",\"translation\":\"in the air going outward\"},{\"word\":\"apānam\",\"translation\":\"the air going downward\"},{\"word\":\"tathā\",\"translation\":\"as also\"},{\"word\":\"apare\",\"translation\":\"others\"},{\"word\":\"prāṇa\",\"translation\":\"of the air going outward\"},{\"word\":\"apāna\",\"translation\":\"and the air going downward\"},{\"word\":\"gatī\",\"translation\":\"the movement\"},{\"word\":\"ruddhvā\",\"translation\":\"checking\"},{\"word\":\"prāṇa-āyāma\",\"translation\":\"trance induced by stopping all breathing\"},{\"word\":\"parāyaṇāḥ\",\"translation\":\"so inclined\"},{\"word\":\"apare\",\"translation\":\"others\"},{\"word\":\"niyata\",\"translation\":\"having controlled\"},{\"word\":\"āhārāḥ\",\"translation\":\"eating\"},{\"word\":\"prāṇān\",\"translation\":\"the outgoing air\"},{\"word\":\"prāṇeṣu\",\"translation\":\"in the outgoing air\"},{\"word\":\"juhvati\",\"translation\":\"sacrifice\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":1469,\"bb\":1303,\"url_path\":\"/en/library/bg/4/29/b1303/\",\"body_value\":\"Still others, who are inclined to the process of breath restraint to remain in trance, practice by offering the movement of the outgoing breath into the incoming, and the incoming breath into the outgoing, and thus at last remain in trance, stopping all breathing. Others, curtailing the eating process, offer the outgoing breath into itself as a sacrifice.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":1470,\"bb\":1304,\"url_path\":\"/en/library/bg/4/29/b1304/\",\"body_value\":\"$25\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":1471,\"bb\":1305,\"url_path\":\"/en/library/bg/4/29/b1305/\",\"body_value\":\"māṁ ca yo ’vyabhicāreṇa
bhakti-yogena sevate
sa guṇān samatītyaitān
brahma-bhūyāya kalpate\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":1472,\"bb\":1306,\"url_path\":\"/en/library/bg/4/29/b1306/\",\"body_value\":\"“One who engages in unalloyed devotional service to the Lord transcends the modes of material nature and is immediately elevated to the spiritual platform.” A Kṛṣṇa conscious person begins from the transcendental stage, and he is constantly in that consciousness. Therefore, there is no falling down, and ultimately he enters into the abode of the Lord without delay. The practice of reduced eating is automatically done when one eats only kṛṣṇa-prasādam, or food which is offered first to the Lord. Reducing the eating process is very helpful in the matter of sense control. And without sense control there is no possibility of getting out of the material entanglement.\"}]}],\"short_title\":\"Bg. 4.29\",\"medium_title\":\"Bhagavad-gītā As It Is 4.29\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L26\",\"$L27\",\"$L28\"]}]\n"])self.__next_f.push([1,"2a:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n30:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n26:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[[\"$\",\"nav\",null,{\"aria-label\":\"Brea