fwundefined-4\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-apānam\",{\"href\":\"/en/search/synonyms/?original=apānam\",\"children\":[\"$\",\"em\",null,{\"children\":\"apānam\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"the air going downward\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-5\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-tathā\",{\"href\":\"/en/search/synonyms/?original=tathā\",\"children\":[\"$\",\"em\",null,{\"children\":\"tathā\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"as also\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-6\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-apare\",{\"href\":\"/en/search/synonyms/?original=apare\",\"children\":[\"$\",\"em\",null,{\"children\":\"apare\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"others\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-7\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-prāṇa\",{\"href\":\"/en/search/synonyms/?original=prāṇa\",\"children\":[\"$\",\"em\",null,{\"children\":\"prāṇa\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"of the air going outward\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-8\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-apāna\",{\"href\":\"/en/search/synonyms/?original=apāna\",\"children\":[\"$\",\"em\",null,{\"children\":\"apāna\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"and the air going downward\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-9\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-gatī\",{\"href\":\"/en/search/synonyms/?original=gatī\",\"children\":[\"$\",\"em\",null,{\"children\":\"gatī\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"the movement\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-10\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-ruddhvā\",{\"href\":\"/en/search/synonyms/?original=ruddhvā\",\"children\":[\"$\",\"em\",null,{\"children\":\"ruddhvā\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"checking\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-11\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-prāṇa\",{\"href\":\"/en/search/synonyms/?original=prāṇa\",\"children\":[\"$\",\"em\",null,{\"children\":\"prāṇa\"}]}],\"-\",[\"$\",\"$L20\",\"wfwundefined-2-āyāma\",{\"href\":\"/en/search/synonyms/?original=āyāma\",\"children\":[\"$\",\"em\",null,{\"children\":\"āyāma\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"trance induced by stopping all breathing\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-12\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-parāyaṇāḥ\",{\"href\":\"/en/search/synonyms/?original=parāyaṇāḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"parāyaṇāḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"so inclined\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-13\",{\"className\":\"inline\",\"children\":[[\"$L32\"],\" — \",\"$L33\",\"; \"]}],\"$L34\",\"$L35\",\"$L36\",\"$L37\",\"$L38\"]}]}]]]}]\n"])self.__next_f.push([1,"2e:[\"$\",\"div\",\"1465-translation,1465-translation\",{\"className\":\"av-translation\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Translation\"}],[[\"$\",\"$L2a\",\"child-1469\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:3:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"children\":[\"$\",\"strong\",null,{\"dangerouslySetInnerHTML\":{\"__html\":\"Still others, who are inclined to the process of breath restraint to remain in trance, practice by offering the movement of the outgoing breath into the incoming, and the incoming breath into the outgoing, and thus at last remain in trance, stopping all breathing. Others, curtailing the eating process, offer the outgoing breath into itself as a sacrifice.\"}}]}]}]]]}]\n"])self.__next_f.push([1,"2f:[\"$\",\"div\",\"1465-purport,1465-purport\",{\"className\":\"av-purport\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Purport\"}],[[\"$\",\"$L2a\",\"child-1470\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"children\":[\"This system of \",[\"$\",\"em\",\"1\",{\"children\":\"yoga\"}],\" for controlling the breathing process is called \",[\"$\",\"em\",\"3\",{\"children\":\"prāṇāyāma,\"}],\" and in the beginning it is practiced in the \",[\"$\",\"em\",\"5\",{\"children\":\"haṭha-yoga\"}],\" system through different sitting postures. All of these processes are recommended for controlling the senses and for advancement in spiritual realization. This practice involves controlling the airs within the body so as to reverse the directions of their passage. The \",[\"$\",\"em\",\"7\",{\"children\":\"apāna\"}],\" air goes downward, and the \",[\"$\",\"em\",\"9\",{\"children\":\"prāṇa\"}],\" air goes up. The \",[\"$\",\"em\",\"11\",{\"children\":\"prāṇāyāma-yogī\"}],\" practices breathing the opposite way until the currents are neutralized into \",[\"$\",\"em\",\"13\",{\"children\":\"pūraka,\"}],\" equilibrium. Offering the exhaled breath into the inhaled breath is called \",[\"$\",\"em\",\"15\",{\"children\":\"recaka.\"}],\" When both air currents are completely stopped, one is said to be in \",[\"$\",\"em\",\"17\",{\"children\":\"kumbhaka-yoga.\"}],\" By practice of \",[\"$\",\"em\",\"19\",{\"children\":\"kumbhaka-yoga,\"}],\" one can increase the duration of life for perfection in spiritual realization. The intelligent \",[\"$\",\"em\",\"21\",{\"children\":\"yogī\"}],\" is interested in attaining perfection in one life, without waiting for the next. For by practicing \",[\"$\",\"em\",\"23\",{\"children\":\"kumbhaka-yoga,\"}],\" the \",[\"$\",\"em\",\"25\",{\"children\":\"yogīs\"}],\" increase the duration of life by many, many years. A Kṛṣṇa conscious person, however, being always situated in the transcendental loving service of the Lord, automatically becomes the controller of the senses. His senses, being always engaged in the service of Kṛṣṇa, have no chance of becoming otherwise engaged. So at the end of life, he is naturally transferred to the transcendental plane of Lord Kṛṣṇa; consequently he makes no attempt to increase his longevity. He is at once raised to the platform of liberation, as stated in \",[\"$\",\"$L20\",\"27\",{\"href\":\"/en/library/bg/14/26/\",\"children\":[[\"$\",\"em\",\"0\",{\"children\":\"Bhagavad-gītā\"}],\" (14.26)\"]}],\":\"]}]}],[\"$\",\"$L2a\",\"child-1471\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:1\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base text-center italic\",\"dangerouslySetInnerHTML\":{\"__html\":\"māṁ ca yo ’vyabhicāreṇa
bhakti-yogena sevate
sa guṇān samatītyaitān
brahma-bhūyāya kalpate\"}}]}],[\"$\",\"$L2a\",\"child-1472\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:2\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"“One who engages in unalloyed devotional service to the Lord transcends the modes of material nature and is immediately elevated to the spiritual platform.” A Kṛṣṇa conscious person begins from the transcendental stage, and he is constantly in that consciousness. Therefore, there is no falling down, and ultimately he enters into the abode of the Lord without delay. The practice of reduced eating is automatically done when one eats only kṛṣṇa-prasādam, or food which is offered first to the Lord. Reducing the eating process is very helpful in the matter of sense control. And without sense control there is no possibility of getting out of the material entanglement.\"}}]}]]]}]\n"])self.__next_f.push([1,"39:[[\"$\",\"source\",null,{\"srcSet\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"media\":\"(prefers-color-scheme: dark)\"}],[\"$\",\"img\",null,{\"src\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"loading\":\"lazy\",\"referrerPolicy\":\"no-referrer\",\"crossOrigin\":\"anonymous\"}]]\n"])self.__next_f.push([1,"27:[\"$\",\"div\",null,{\"id\":\"footer\",\"className\":\"mt-auto w-full max-w-7xl mx-auto pt-3 mb-6 text-sm text-vb-normal-text/80 text-center\",\"children\":[[\"$\",\"$L1f\",null,{\"donors\":\"Shweta Saxena; Gopalakrishnan Soundarajan;    Kuldip Persaud;  Raghava Chandra Dasa; Shubhangi Rajiv Panjiyar; Suparna Kotaru;  Rajendra and Geeta Ramchandani;  Jaykumar Prabhakar; Bharat Vyas; Shri Chander Mohan Gilhotra, HG Prashant Mukund Das, Shri Trilok Singh Grover, HG Bhakta Mitra Das, Laxmi Narayan Agarwal; Ronak Talati; Bhargav Ashok; Akiralali; Rajasa das; Riya and Tejal Chopade; Indradyumna Swami; Jai Devaki Parks;  Ashmi Chakrabor